METAMON_TEAM_SETS = {
    "competitive",  # human-made sample teams, usually from the Smogon forums
    "modern_replays",  # predicted teams based on recent replays using the best prediction strategy we have available for each generation
    "modern_replays_v2",  # an updated/expanded version of modern_replays (September 2025) that was verified against the PokéAgent Challenge server's frozen teambuilder rules
    "paper_replays",  # predicted teams from replays. backwards compatible with a team set mentioned in the paper
    "paper_variety",  # procedurally generated teams with unrealistic OOD lead-off Pokémon. Movesets were generated by sampling from all-time usage stats.
}


class TeamSet(Teambuilder):
    """Sample from a directory of Showdown team files.

    A simple wrapper around poke-env's Teambuilder that randomly samples a team from a
    directory of team files.

    Args:
        team_file_dir: The directory containing the team files (searched recursively).
            Team files are just text files in the standard Showdown export format. See
            https://pokepast.es/syntax.html for details.
        battle_format: The battle format of the team files (e.g. "gen1ou", "gen2ubers",
            etc.). Note that we assume files have a matching extension (e.g.
            "any_name.gen1ou_team").
    """

    def __init__(self, team_file_dir: str, battle_format: str):
        super().__init__()
        self.team_file_dir = team_file_dir
        self.battle_format = battle_format.lower()
        self.team_files = self._find_team_files()
        self._most_recent_team_file = None

    def _find_team_files(self) -> List[str]:
        team_files = []
        for root, _, files in os.walk(self.team_file_dir):
            for file in files:
                if file.endswith(f".{self.battle_format}_team"):
                    team_files.append(os.path.join(root, file))
        return team_files

    def block_team(self, packed_team: str) -> bool:
        """
        Reject True to reject the team and resample.

        Override to quick-fix team selection in the event of minor rule changes.

        Args:
            packed_team: Showdown team string in the "packed" format (e.g. Brambleghast||lifeorb|windrider|poltergeist|...)

        Returns:
            bool: True to reject the team and resample.
        """
        return False

    @property
    def most_recent_team_file(self) -> Optional[str]:
        return self._most_recent_team_file

    def yield_team(self) -> str:
        for attempt in range(100):
            # read team from disk
            file = random.choice(self.team_files)
            self._most_recent_team_file = file
            with open(file, "r") as f:
                team_data = f.read()
            # check team
            candidate_team = self.join_team(self.parse_showdown_team(team_data))
            if not self.block_team(candidate_team):
                return candidate_team
            if attempt % 10 == 0:
                warnings.warn(f"Failed to find valid team after {attempt + 1} attempts")
        raise RuntimeError(f"Could not find valid team after 100 attempts")


class PokeAgentTeamSet(TeamSet):
    """
    The PokéAgent Challenge uses the June 2025 Showdown rules with bans on Zoroark/Zorua and Revival Blessing.

    This is a hot-patch to remove zoroark/zorua and revival blessing from summer 2025 procedurally generated teamsets
    """

    def block_team(self, packed_team: str) -> bool:
        if self.battle_format == "gen9ou":
            packed_team_lower = packed_team.lower()
            if "zoroark" in packed_team_lower or "zorua" in packed_team_lower:
                return True
            elif "revivalblessing" in packed_team_lower:
                return True
        return False


def get_metamon_teams(
    battle_format: str, set_name: str, set_type: Type[TeamSet] = TeamSet
) -> TeamSet:
    """
    Download a set of teams from huggingface (if necessary) and return a TeamSet.

    Args:
        battle_format: The battle format of the team files (e.g. "gen1ou", "gen2ubers", etc.).
        set_name: The name of the set of teams to download. See the README for options. If a custom name is provided,
            we will search the `METAMON_CACHE_DIR` for a custom team set with that name.
        set_type: The type of TeamSet to return. Defaults to TeamSet.
    """
    if set_name in METAMON_TEAM_SETS:
        path = download_teams(battle_format, set_name=set_name)
    elif metamon.METAMON_CACHE_DIR is not None:
        path = os.path.join(metamon.METAMON_CACHE_DIR, "teams", set_name)
    else:
        raise ValueError(f"`METAMON_CACHE_DIR` environment variable is not set!")
    if not os.path.exists(path):
        raise ValueError(
            f"Cannot locate valid team directory for format {battle_format} at path {path}"
        )
    return set_type(path, battle_format)


def _check_avatar(avatar: str):
    if avatar is None:
        return
    with open(os.path.join(DATA_PATH, "avatar_names.txt"), "r") as f:
        options = [l.strip() for l in f.readlines()]
    if avatar not in options:
        raise ValueError(
            f"Avatar {avatar} is not valid. See https://play.pokemonshowdown.com/sprites/trainers/ for a list of options."
        )
    else:
        return avatar


class PokeEnvWrapper(OpenAIGymEnv):
    """A thin wrapper around poke-env's OpenAIGymEnv that handles the observation space,
    action space, and reward function while adding some basic conveniences with lazy initialization.

    Args:
        battle_format: The battle format of the team files (e.g. "gen1ou", "gen2ubers",
            etc.).
        observation_space: The observation space to use. Must be an instance of
            `interface.ObservationSpace`.
        reward_function: The reward function to use. Must be an instance of
            `interface.RewardFunction`.
        player_team_set: The team set to use for the player. Must be an instance of
            `TeamSet` or a poke-env TeamBuilder.
        opponent_type: The type of opponent to use. Must be a callable that creates a
            `poke_env.player.Player`. All the `metamon.baselines` implement this.
        opponent_team_set: The team set to use for the opponent. Must be an instance of
            `TeamSet` or a poke-env TeamBuilder. If the opponent set is not specified,
            the opponent plays with the same team set (but an independently sampled team)
            as the player.
        player_username: The username to use for the player. If not specified, a random
            username will be generated. It is important for this to be unique across
            parallel environments.
        player_password: The password to use for the player. This is usually not needed
            on the local server.
        opponent_username: The username to use for the opponent. If not specified, a
            random username will be generated. It is important for this to be unique
            across parallel environments.
        player_avatar: The avatar for the player when viewing battles in your browser.
            See https://play.pokemonshowdown.com/sprites/trainers/ for a list of
            options.
        opponent_avatar: The avatar for the opponent when viewing battles in your
            browser. See https://play.pokemonshowdown.com/sprites/trainers/ for a list
            of options.
        start_challenging: Whether to start challenging the opponent immediately. This
            is a poke-env detail handled by the other wrappers.
        start_timer_on_battle_start: Start the time increment controls that prevent
            infinite battles from inactive players.
        turn_limit: The maximum number of turns in a battle. Note that Showdown already
            enforces a limit of 1000 regardless of this setting.
        save_trajectories_to: The directory to save the trajectories to. Data is saved
            in the same format as the parsed replay dataset.
        save_team_results_to: Directory to write some basic stats about team choice and battle outcome
            for use in tuning team selection. Data is saved in a CSV file with columns:
            Player Username, Team File, Opponent Username, Result, Turn Count, Battle ID.
        battle_backend: The Showdown state parsing backend. Options are 'poke-env' or
            'metamon'.
    """

    _INIT_RETRIES = 250

    def __init__(
        self,
        battle_format: str,
        observation_space: ObservationSpace,
        action_space: ActionSpace,
        reward_function: RewardFunction,
        player_team_set: TeamSet,
        opponent_type: Optional[Type[Player]] = None,
        opponent_team_set: Optional[TeamSet] = None,
        player_username: Optional[str] = None,
        player_password: Optional[str] = None,
        opponent_username: Optional[str] = None,
        player_avatar: Optional[str] = None,
        opponent_avatar: Optional[str] = None,
        start_challenging: bool = True,
        start_timer_on_battle_start: bool = False,
        turn_limit: int = 1000,
        save_trajectories_to: Optional[str] = None,
        save_team_results_to: Optional[str] = None,
        battle_backend: str = "poke-env",
    ):
        # Mark as not initialized for lazy initialization
        self._initialized = False

        # Store all initialization parameters for later
        self._init_params = {
            'battle_format': battle_format,
            'observation_space': observation_space,
            'action_space': action_space,
            'reward_function': reward_function,
            'player_team_set': player_team_set,
            'opponent_type': opponent_type,
            'opponent_team_set': opponent_team_set,
            'player_username': player_username,
            'player_password': player_password,
            'opponent_username': opponent_username,
            'player_avatar': player_avatar,
            'opponent_avatar': opponent_avatar,
            'start_challenging': start_challenging,
            'start_timer_on_battle_start': start_timer_on_battle_start,
            'turn_limit': turn_limit,
            'save_trajectories_to': save_trajectories_to,
            'save_team_results_to': save_team_results_to,
            'battle_backend': battle_backend,
        }

        # Set up attributes that don't require network connections
        self._setup_basic_attributes()

    def _setup_basic_attributes(self):
        """Set up attributes that don't require network connections."""
        params = self._init_params
        opponent_team_set = params['opponent_team_set'] or copy.deepcopy(params['player_team_set'])
        random_username = (
            lambda: f"MM-{''.join(str(random.randint(0, 9)) for _ in range(10))}"
        )
        self.player_username = params['player_username'] or random_username()
        self.opponent_username = params['opponent_username'] or random_username()

        # Store configurations for later use
        self.player_account_configuration = AccountConfiguration(
            self.player_username, params['player_password']
        )
        self.opponent_account_configuration = AccountConfiguration(
            self.opponent_username, None
        )
        if params['save_trajectories_to'] is not None:
            self.save_trajectories_to = os.path.join(
                params['save_trajectories_to'], params['battle_format']
            )
            os.makedirs(self.save_trajectories_to, exist_ok=True)
        else:
            self.save_trajectories_to = None

        if params['save_team_results_to'] is not None:
            os.makedirs(params['save_team_results_to'], exist_ok=True)
            self.save_team_results_to = os.path.join(
                params['save_team_results_to'],
                f"battle_log_{self.player_username}_{params['battle_format']}.csv",
            )
            if not os.path.exists(self.save_team_results_to):
                with open(self.save_team_results_to, "a") as f:
                    f.write(
                        "Player Username, Team File, Opponent Username, Result, Turn Count, Battle ID\n"
                    )
        else:
            self.save_team_results_to = None

        # Store opponent info for lazy initialization
        self.metamon_opponent_name = params['opponent_type'].__name__ if params['opponent_type'] else None
        self._current_opponent = None  # Will be created during lazy init

        # Copy these immediately as they don't involve network connections
        self.reward_function = copy.deepcopy(params['reward_function'])
        self.metamon_obs_space = copy.deepcopy(params['observation_space'])
        self.metamon_action_space = copy.deepcopy(params['action_space'])
        self.metamon_team_set = params['player_team_set']
        self.turn_limit = params['turn_limit']
        self.metamon_battle_format = params['battle_format']

        # Initialize lazy space storage
        self._lazy_action_space = self.metamon_action_space.gym_space
        self._lazy_observation_space = self.metamon_obs_space.gym_space

        # Determine player class for later
        if params['battle_backend'] == "poke-env":
            self.player_class = Player
        elif params['battle_backend'] == "metamon":
            self.player_class = MetamonPlayer
        else:
            raise ValueError(
                f"Invalid battle backend: {params['battle_backend']}. Options are 'poke-env' or 'metamon'."
            )

        # Store other parameters needed for parent init
        self._checked_player_avatar = _check_avatar(params['player_avatar'])
        self._checked_opponent_avatar = _check_avatar(params['opponent_avatar'])

    def _ensure_initialized(self):
        """Initialize the actual Player connections if not already done."""
        if self._initialized:
            return

        params = self._init_params
        print(
            f"[DEBUG] _ensure_initialized: player_username={self.player_username} "
            f"battle_format={params['battle_format']} backend={getattr(self, 'player_class', type(None)).__name__}",
            flush=True,
        )
        try:
            has_parent_env_move = hasattr(OpenAIGymEnv, "_env_move")
            print(
                f"[DEBUG] _ensure_initialized: OpenAIGymEnv has _env_move={has_parent_env_move}",
                flush=True,
            )
        except Exception:
            pass

        # Create opponent if needed
        if params['opponent_type'] is not None:
            opponent_team_set = params['opponent_team_set'] or copy.deepcopy(params['player_team_set'])
            print(
                f"[DEBUG] _ensure_initialized: creating opponent type={params['opponent_type'].__name__} "
                f"opponent_username={self.opponent_username}",
                flush=True,
            )
            self._current_opponent = params['opponent_type'](
                battle_format=params['battle_format'],
                team=opponent_team_set,
                account_configuration=self.opponent_account_configuration,
                server_configuration=self.server_configuration,
                avatar=self._checked_opponent_avatar,
                ping_timeout=None,
            )

        # Initialize parent class (creates Player with network connection)
        sc = self.server_configuration
        try:
            ws = getattr(sc, 'ws_url', None)
            au = getattr(sc, 'auth_url', None)
            print(
                f"[DEBUG] _ensure_initialized: connecting ws={ws or 'LocalhostServerConfiguration'} auth={au or ''}",
                flush=True,
            )
        except Exception:
            pass
        # Build kwarg set compatible with both old/new poke-env wrappers
        base_init = getattr(OpenAIGymEnv, "__init__", None)
        base_params = set()
        if base_init is not None:
            try:
                base_params = set(inspect.signature(base_init).parameters.keys())
            except Exception:
                base_params = set()

        kwargs = dict(
            battle_format=params['battle_format'],
            server_configuration=self.server_configuration,
            account_configuration=self.player_account_configuration,
            team=params['player_team_set'],
            avatar=self._checked_player_avatar,
            start_timer_on_battle_start=params['start_timer_on_battle_start'],
            start_challenging=params['start_challenging'],
        )
        # Newer wrappers accept selecting the underlying player class via 'player_class'
        if 'player_class' in base_params:
            kwargs['player_class'] = self.player_class
        # Older EnvPlayer path expects an explicit 'opponent' argument
        if 'opponent' in base_params:
            # Provide an opponent if one was constructed; otherwise, use None
            # (poke-env will handle laddering without a pre-specified opponent).
            kwargs['opponent'] = getattr(self, '_current_opponent', None)

        super().__init__(**kwargs)
        print(f"[DEBUG] _ensure_initialized: Player initialized username={self.player_username}", flush=True)
        try:
            has_self_env_move = hasattr(self, "_env_move")
            print(
                f"[DEBUG] _ensure_initialized: self has _env_move={has_self_env_move}",
                flush=True,
            )
        except Exception:
            pass

        # Ensure a valid team preview response is available and bound across versions
        try:
            self._bind_teampreview()
        except Exception:
            pass

        # Install extra preview debug logging at the Player level (once)
        try:
            self._install_player_preview_debug()
        except Exception:
            pass

        # Patch _AsyncPlayer preview path so it returns '/team ...' during teampreview
        try:
            self._install_asyncplayer_preview_patch()
        except Exception:
            pass

        self._initialized = True

    @property
    def server_configuration(self):
        """Server configuration for local Showdown.

        Defaults to localhost:8000 (poke-env's LocalhostServerConfiguration),
        but can be overridden with environment variables:
          - SHOWDOWN_HOST: hostname/IP to connect to (default: 127.0.0.1)
          - SHOWDOWN_PORT: port to connect to (default: 8000)
          - PORT: fallback when SHOWDOWN_PORT is not set (useful in containers)
        """
        host = os.environ.get("SHOWDOWN_HOST", "127.0.0.1")
        port = os.environ.get("SHOWDOWN_PORT") or os.environ.get("PORT") or "8000"
        try:
            port_int = int(port)
        except Exception:
            port_int = 8000

        # Use poke-env's built-in LocalhostServerConfiguration when matching defaults
        if host in {"127.0.0.1", "localhost"} and port_int == 8000:
            print(
                f"[DEBUG] server_configuration: LocalhostServerConfiguration host={host} "
                f"port=8000 (env SHOWDOWN_HOST={os.environ.get('SHOWDOWN_HOST')} "
                f"SHOWDOWN_PORT={os.environ.get('SHOWDOWN_PORT')} PORT={os.environ.get('PORT')})",
                flush=True,
            )
            return LocalhostServerConfiguration

        # Otherwise, construct a custom configuration for the given host/port
        ws_url = f"ws://{host}:{port_int}/showdown/websocket"
        auth_url = f"http://{host}:{port_int}/action.php?"
        print(f"[DEBUG] server_configuration: custom ServerConfiguration ws={ws_url} auth={auth_url}", flush=True)
        return ServerConfiguration(ws_url, auth_url)

    @property
    def action_space(self):
        """Return action space, works even before full initialization."""
        # During lazy init, or immediately after parent init, the backing
        # attribute may not yet exist. Fall back to the lazy field.
        if getattr(self, "_initialized", False) and hasattr(self, "_action_space"):
            return self._action_space
        return getattr(self, "_lazy_action_space", None)

    @action_space.setter
    def action_space(self, value):
        """Set action space."""
        if self._initialized:
            # Delegate to parent if initialized
            object.__setattr__(self, '_action_space', value)
        else:
            # Store locally before initialization
            self._lazy_action_space = value

    @property
    def observation_space(self):
        """Return observation space, works even before full initialization."""
        if getattr(self, "_initialized", False) and hasattr(
            self, "_observation_space"
        ):
            return self._observation_space
        return getattr(self, "_lazy_observation_space", None)

    @observation_space.setter
    def observation_space(self, value):
        """Set observation space."""
        if self._initialized:
            # Delegate to parent if initialized
            object.__setattr__(self, '_observation_space', value)
        else:
            # Store locally before initialization
            self._lazy_observation_space = value

    def get_opponent(self):
        return self._current_opponent

    def close(self, purge: bool = True):
        """Close environment, handling lazy initialization."""
        if not self._initialized:
            # If never initialized, nothing to close
            return
        # Otherwise delegate to parent
        super().close(purge=purge)

    def action_space_size(self):
        return self.metamon_action_space.gym_space.n

    def on_invalid_order(self, battle: Battle):
        return self.choose_random_move(battle)

    def reset(self, *args, **kwargs):
        # Ensure initialization before first use
        self._ensure_initialized()

        self.metamon_obs_space.reset()
        self.invalid_action_counter = 0
        self.valid_action_counter = 0
        self.turn_counter = 0
        self.battle_reference = self.agent.n_won_battles
        obs, info = super().reset(*args, **kwargs)
        self._most_recent_state = UniversalState.from_Battle(self.current_battle)
        self._update_legal_actions(self._most_recent_state, self.current_battle)
        info["legal_actions"] = self._most_recent_legal_actions
        self.trajectory = {"states": [self._most_recent_state], "actions": []}
        return obs, info

    def action_to_move(self, action: Any, battle: Battle):
        universal_state = UniversalState.from_Battle(battle)
        universal_action = self.metamon_action_space.agent_output_to_action(
            state=universal_state, agent_output=action
        )
        battle_order = universal_action.to_BattleOrder(battle)
        if battle_order is None:
            self.invalid_action_counter += 1
            print(f"[DEBUG] action_to_move: action={action} -> INVALID (fallback)", flush=True)
            return self.on_invalid_order(battle)
        else:
            self.valid_action_counter += 1
            try:
                msg = getattr(battle_order, 'message', '<no-message>')
            except Exception:
                msg = '<no-message>'
            print(f"[DEBUG] action_to_move: action={action} -> VALID order={type(battle_order).__name__} msg={msg}", flush=True)
            return battle_order

    def describe_embedding(self) -> gym.spaces.Space:
        return self.metamon_obs_space.gym_space

    def calc_reward(self, last_battle: Battle, current_battle: Battle) -> float:
        last_state = UniversalState.from_Battle(last_battle)
        state = UniversalState.from_Battle(current_battle)
        reward = self.reward_function(last_state, state)
        return reward

    def _update_legal_actions(self, state: UniversalState, battle: Battle):
        legal_actions = UniversalAction.definitely_valid_actions(
            state=state, battle=battle
        )
        self._most_recent_legal_actions = [
            self.metamon_action_space.action_to_agent_output(state=state, action=action)
            for action in legal_actions
        ]
        return self._most_recent_legal_actions

    def embed_battle(self, battle: Battle):
        universal_state = UniversalState.from_Battle(battle)
        self._most_recent_state = universal_state
        legal = self._update_legal_actions(universal_state, battle)
        try:
            turn = getattr(battle, 'turn', None)
            print(f"[DEBUG] embed_battle: turn={turn} legal_actions={legal}", flush=True)
        except Exception:
            pass
        return self.metamon_obs_space.state_to_obs(universal_state)

    def step(self, action):
        # Ensure initialization before first use
        self._ensure_initialized()

        self.turn_counter += 1
        print(f"[DEBUG] step: action={action}", flush=True)
        next_obs, reward, terminated, truncated, info = super().step(action)
        print(f"[DEBUG] step: reward={reward} terminated={terminated} truncated={truncated}", flush=True)
        info["legal_actions"] = self._most_recent_legal_actions
        if self.save_trajectories_to is not None:
            self.trajectory["states"].append(self._most_recent_state)
            self.trajectory["actions"].append(
                self.metamon_action_space.agent_output_to_action(
                    state=self._most_recent_state, agent_output=action
                ).action_idx
            )

        # enforce simple turn limit
        hit_time_limit = self.turn_counter > self.turn_limit
        terminated |= hit_time_limit
        truncated |= hit_time_limit
        if terminated or truncated:
            # logging info
            info["valid_action_count"] = self.valid_action_counter
            info["invalid_action_count"] = self.invalid_action_counter
            info["won"] = self.agent.n_won_battles > self.battle_reference
            self.battle_reference = self.agent.n_won_battles

            if (
                self.save_trajectories_to is not None
                or self.save_team_results_to is not None
            ):
                # build a long filename that matches the format of the parsed replay dataset
                result = "WIN" if info["won"] == 1 else "LOSS"
                battle_id = "".join(str(random.randint(0, 9)) for _ in range(10))
                timestamp = datetime.now().strftime("%m-%d-%Y-%H:%M:%S")
                opponent_name = (
                    self.metamon_opponent_name or self.current_battle.opponent_username
                )

                if self.save_trajectories_to is not None:
                    filename = f"metamon-{self.metamon_battle_format}-{battle_id}_Unrated_{self.player_username}_vs_{opponent_name}_{timestamp}_{result}.json.lz4"
                    # matches the format of the parsed replay dataset
                    output_json = {
                        "states": [s.to_dict() for s in self.trajectory["states"]],
                        # NOTE: the replay parser leaves a blank (-1) final action; matched here
                        "actions": self.trajectory["actions"] + [-1],
                    }
                    # conservative file writing to avoid partial writes on shutdown or interruption
                    # when launching multiple environments in parallel
                    path = os.path.join(self.save_trajectories_to, filename)
                    temp_path = path + ".tmp"
                    with lz4.frame.open(temp_path, "wb") as f:
                        f.write(json.dumps(output_json).encode("utf-8"))
                    os.rename(temp_path, path)

                if self.save_team_results_to is not None:
                    with open(self.save_team_results_to, "a") as f:
                        f.write(
                            f"{self.player_username},{self.metamon_team_set.most_recent_team_file},{opponent_name},{result},{self.turn_counter},{battle_id}\n"
                        )

        return next_obs, reward, terminated, truncated, info

    def take_long_break(self):
        # Only close if we've been initialized
        if self._initialized:
            self.close(purge=False)
        self.reset_battles()

    # ---- Team Preview (base) ----
    # Always provide a sane default: pick all slots in natural order.
    def teampreview(self, battle: Battle) -> str:  # type: ignore[override]
        try:
            size = getattr(battle, "max_team_size", None)
            if not isinstance(size, int) or size <= 0:
                size = len(getattr(battle, "team", {})) or 6
        except Exception:
            size = 6
        order = "".join(str(i + 1) for i in range(size))
        return f"/team {order}"

    # Some older OpenAI-Gym wrappers query an env-level hook; keep it in sync.
    def _env_teampreview(self, battle: Battle) -> str:
        return self.teampreview(battle)

    def _bind_teampreview(self):
        """Bind self.teampreview onto all underlying Player objects used by the env."""
        try:
            from poke_env.player import Player as _PEPlayer
        except Exception:
            return

        def _bind_on(obj):
            try:
                bound = self.teampreview.__get__(obj, obj.__class__)
                setattr(obj, "teampreview", bound)
            except Exception:
                pass

        # If *we* are a Player (fallback path), bind on self as well.
        if isinstance(self, _PEPlayer):
            _bind_on(self)

        # Common attribute names across poke-env versions
        bound_attrs = []
        for name in ("agent", "player", "env_player", "single_player", "_player", "_agent"):
            obj = getattr(self, name, None)
            if isinstance(obj, _PEPlayer):
                _bind_on(obj)
                bound_attrs.append(name)

        # Scan remaining attributes just in case (future compatibility)
        try:
            for _, obj in vars(self).items():
                if isinstance(obj, _PEPlayer):
                    _bind_on(obj)
                    bound_attrs.append("<var>")
        except Exception:
            pass

        # Also bind on the lazily-created opponent if we made one
        opp = getattr(self, "_current_opponent", None)
        if isinstance(opp, _PEPlayer):
            _bind_on(opp)
            bound_attrs.append("_current_opponent")

        try:
            print(
                f"[DEBUG] _bind_teampreview: bound on attrs={bound_attrs if bound_attrs else 'none'}",
                flush=True,
            )
        except Exception:
            pass

    # Heuristic preview detector that works across poke-env versions
    def _is_teampreview(self, battle: Battle) -> bool:
        try:
            if getattr(battle, "teampreview", None):
                return True
            turn = int(getattr(battle, "turn", 0))
            if turn != 0:
                return False
            if getattr(battle, "max_team_size", None):
                return True
            if getattr(battle, "active_pokemon", None) is None:
                return True
        except Exception:
            pass
        return False

    # Intercept Team Preview for older gym wrappers that route all requests through this hook
    def _env_move(self, battle: Battle):  # type: ignore[override]
        try:
            turn = getattr(battle, "turn", None)
            mts = getattr(battle, "max_team_size", None)
            has_tp_attr = getattr(battle, "teampreview", None) is not None
            has_active = getattr(battle, "active_pokemon", None) is not None
            print(
                f"[DEBUG] _env_move: called (turn={turn} max_team_size={mts} teampreview_attr={has_tp_attr} active_present={has_active})",
                flush=True,
            )
        except Exception:
            pass

        if self._is_teampreview(battle):
            choice = self.teampreview(battle)
            # Ensure correct prefix
            clean = choice.strip()
            if not clean.startswith("/team"):
                if clean.startswith("team"):
                    clean = "/" + clean
                else:
                    clean = self.teampreview(battle)
            print(f"[DEBUG] _env_move (preview): returning '{clean}'", flush=True)
            return _OrderStub(clean)

        # Defer to parent path when not in preview
        parent_env_move = getattr(OpenAIGymEnv, "_env_move", None)
        if parent_env_move is not None:
            try:
                print("[DEBUG] _env_move: delegating to parent _env_move", flush=True)
            except Exception:
                pass
            return parent_env_move(self, battle)
        # Fallback: delegate to agent/Player choose_move via __getattr__
        try:
            print("[DEBUG] _env_move: delegating to choose_move (fallback)", flush=True)
        except Exception:
            pass
        return self.choose_move(battle)

    def _install_player_preview_debug(self):
        """Monkey-patch poke_env Player preview paths to emit debug logs once.

        Helps confirm which hook is used by the installed poke-env version.
        """
        try:
            from poke_env.player.player import Player as _BasePlayer
        except Exception:
            return
        if getattr(_BasePlayer, "_metamon_preview_debug_installed", False):
            return

        # Patch Player.teampreview to log what it returns
        try:
            _orig_teampreview = _BasePlayer.teampreview  # type: ignore[attr-defined]

            def _patched_teampreview(self, battle):  # type: ignore[no-redef]
                try:
                    choice = _orig_teampreview(self, battle)
                except Exception as e:
                    print(f"[DEBUG] Player.teampreview raised: {e}", flush=True)
                    raise
                print(f"[DEBUG] Player.teampreview: returning '{choice}'", flush=True)
                return choice

            setattr(_BasePlayer, "teampreview", _patched_teampreview)
        except Exception:
            pass

        # Patch Player._handle_battle_request to log when preview requests happen
        try:
            _orig_hbr = _BasePlayer._handle_battle_request  # type: ignore[attr-defined]

            async def _patched_hbr(self, battle, from_teampreview_request=False):  # type: ignore[no-redef]
                try:
                    print(
                        f"[DEBUG] Player._handle_battle_request: from_teampreview_request={from_teampreview_request}",
                        flush=True,
                    )
                except Exception:
                    pass
                return await _orig_hbr(
                    self, battle, from_teampreview_request=from_teampreview_request
                )

            setattr(_BasePlayer, "_handle_battle_request", _patched_hbr)
        except Exception:
            pass

        # Patch Player.choose_move to observe normal path usage
        try:
            import inspect as _inspect
            _orig_choose = _BasePlayer.choose_move  # type: ignore[attr-defined]

            if _inspect.iscoroutinefunction(_orig_choose):

                async def _patched_choose(self, battle):  # type: ignore[no-redef]
                    print("[DEBUG] Player.choose_move: entered", flush=True)
                    choice = await _orig_choose(self, battle)
                    try:
                        msg = getattr(choice, 'message', None)
                        print(
                            f"[DEBUG] Player.choose_move: returned type={type(choice).__name__} msg={msg}",
                            flush=True,
                        )
                    except Exception:
                        pass
                    return choice

                setattr(_BasePlayer, "choose_move", _patched_choose)
            else:

                def _patched_choose(self, battle):  # type: ignore[no-redef]
                    print("[DEBUG] Player.choose_move: entered", flush=True)
                    choice = _orig_choose(self, battle)
                    try:
                        msg = getattr(choice, 'message', None)
                        print(
                            f"[DEBUG] Player.choose_move: returned type={type(choice).__name__} msg={msg}",
                            flush=True,
                        )
                    except Exception:
                        pass
                    return choice

                setattr(_BasePlayer, "choose_move", _patched_choose)
        except Exception:
            pass

        # Patch Player._env_move if present to trace through
        try:
            _orig_penv = getattr(_BasePlayer, "_env_move", None)
            if _orig_penv is not None:
                def _patched_penv(self, battle):  # type: ignore
                    print("[DEBUG] Player._env_move: entered", flush=True)
                    ret = _orig_penv(self, battle)
                    try:
                        msg = getattr(ret, 'message', None)
                        print(
                            f"[DEBUG] Player._env_move: returned type={type(ret).__name__} msg={msg}",
                            flush=True,
                        )
                    except Exception:
                        pass
                    return ret

                setattr(_BasePlayer, "_env_move", _patched_penv)
        except Exception:
            pass

        setattr(_BasePlayer, "_metamon_preview_debug_installed", True)

    def _install_asyncplayer_preview_patch(self):
        """Patch poke_env.player.openai_api._AsyncPlayer._env_move to handle Team Preview.

        Some versions route all requests (including preview) through _AsyncPlayer._env_move.
        This ensures a '/team ...' string is returned at preview time.
        """
        try:
            from poke_env.player.openai_api import _AsyncPlayer  # type: ignore
        except Exception:
            return
        if getattr(_AsyncPlayer, "_metamon_preview_patch_installed", False):
            return

        orig = getattr(_AsyncPlayer, "_env_move", None)
        if orig is None:
            return

        def _patched_env_move(self_ap, battle: Battle, *args, **kwargs):  # type: ignore
            try:
                print("[DEBUG] _AsyncPlayer._env_move: entered", flush=True)
            except Exception:
                pass
            try:
                env = getattr(self_ap, "env", None)
                # Detect preview via env helper if available, else heuristics
                is_preview = False
                if env is not None and hasattr(env, "_is_teampreview"):
                    is_preview = env._is_teampreview(battle)  # type: ignore[attr-defined]
                else:
                    turn = int(getattr(battle, "turn", 0))
                    is_preview = (turn == 0) and (
                        getattr(battle, "max_team_size", None) is not None
                        or getattr(battle, "active_pokemon", None) is None
                    )
                try:
                    print(f"[DEBUG] _AsyncPlayer._env_move: is_preview={is_preview}", flush=True)
                except Exception:
                    pass
                if is_preview:
                    # Build the '/team ...' string inline to avoid super()-related issues
                    try:
                        size_attr = getattr(battle, "max_team_size", None)
                        if isinstance(size_attr, int) and size_attr > 0:
                            size = size_attr
                        else:
                            team = getattr(battle, "team", None)
                            size = len(team) if isinstance(team, dict) and team else 6
                        clean = "/team " + "".join(str(i + 1) for i in range(int(size)))
                    except Exception:
                        clean = "/team 123456"
                    print(f"[DEBUG] _AsyncPlayer._env_move (preview): returning '{clean}'", flush=True)
                    return _OrderStub(clean)
            except Exception as e:
                try:
                    print(f"[DEBUG] _AsyncPlayer._env_move: preview patch error: {e}", flush=True)
                except Exception:
                    pass
            # Non-preview or on error: forward to original
            try:
                print("[DEBUG] _AsyncPlayer._env_move (normal): delegating to original", flush=True)
            except Exception:
                pass
            choice = orig(self_ap, battle, *args, **kwargs)
            try:
                msg = getattr(choice, 'message', None)
                print(f"[DEBUG] _AsyncPlayer._env_move (normal): returned choice type={type(choice).__name__} msg={msg}", flush=True)
            except Exception:
                pass
            return choice

        setattr(_AsyncPlayer, "_env_move", _patched_env_move)
        setattr(_AsyncPlayer, "_metamon_preview_patch_installed", True)

    def resume_from_break(self):
        # Only start challenging if we've been initialized
        if self._initialized:
            self.start_challenging()


class BattleAgainstBaseline(PokeEnvWrapper):
    """
    Battle against a specified opponent.

    Can be used to battle any opponent that connects via the poke-env interface
    (e.g., any baseline in the `baselines` module, or any other custom `Player`)

    Assumes the player and opponent are both sampling from the same set of team files.
    """

    def __init__(
        self,
        battle_format: str,
        observation_space: ObservationSpace,
        action_space: ActionSpace,
        reward_function: RewardFunction,
        team_set: TeamSet,
        opponent_type: Type[Player],
        turn_limit: int = 200,
        save_trajectories_to: Optional[str] = None,
        save_team_results_to: Optional[str] = None,
        battle_backend: str = "poke-env",
    ):
        super().__init__(
            battle_format=battle_format,
            observation_space=observation_space,
            action_space=action_space,
            reward_function=reward_function,
            player_team_set=team_set,
            opponent_team_set=team_set,
            opponent_type=opponent_type,
            turn_limit=turn_limit,
            save_trajectories_to=save_trajectories_to,
            save_team_results_to=save_team_results_to,
            battle_backend=battle_backend,
        )


class QueueOnLocalLadder(PokeEnvWrapper):
    """
    Battle against an opponent by queueing for ladder matches on the local server.

    Can be used to battle any opponent that plays with the Showdown API
    (e.g. humans, your own ML baselines, third-party heuristic bots, etc.).

    Create the environment, start laddering with the opponent, and the battle(s) will begin
    when both players are connected.
    """

    # increases time to launch opponent envs before ladder loop times out ("Agent is not challenging")
    _INIT_RETRIES = 1000

    def __init__(
        self,
        battle_format: str,
        num_battles: Optional[int],
        observation_space: ObservationSpace,
        action_space: ActionSpace,
        reward_function: RewardFunction,
        player_team_set: TeamSet,
        player_username: str,
        player_avatar: Optional[str] = None,
        start_timer_on_battle_start: bool = True,
        save_trajectories_to: Optional[str] = None,
        save_team_results_to: Optional[str] = None,
        player_password: Optional[str] = None,
        battle_backend: str = "poke-env",
        print_battle_bar: bool = True,
    ):
        super().__init__(
            battle_format=battle_format,
            observation_space=observation_space,
            action_space=action_space,
            reward_function=reward_function,
            player_team_set=player_team_set,
            player_username=player_username,
            player_password=player_password,
            player_avatar=player_avatar,
            start_timer_on_battle_start=start_timer_on_battle_start,
            opponent_type=None,
            start_challenging=False,
            turn_limit=float("inf"),
            save_trajectories_to=save_trajectories_to,
            save_team_results_to=save_team_results_to,
            battle_backend=battle_backend,
        )
        print(f"Laddering for {num_battles} battles", flush=True)
        self.print_battle_bar = print_battle_bar
        self.player_username = player_username
        self.player_password = player_password
        self.num_battles = num_battles
        self._ensure_initialized()
        print(
            f"[DEBUG] QueueOnLocalLadder: initialized username={self.player_username} "
            f"server={os.environ.get('SHOWDOWN_HOST', '127.0.0.1')}:{os.environ.get('SHOWDOWN_PORT') or os.environ.get('PORT') or '8000'}",
            flush=True,
        )
        self.handle_ladder_start(n_challenges=num_battles)

    def handle_ladder_start(self, n_challenges: int):
        # hook to allow throttling on pokeagent ladder
        print(f"[DEBUG] handle_ladder_start: start_laddering n_challenges={n_challenges}", flush=True)
        return self.start_laddering(n_challenges=n_challenges)

    def step(self, action):
        next_state, reward, terminated, truncated, info = super().step(action)
        if self.print_battle_bar:
            self.render()
        return next_state, reward, terminated, truncated, info

    # ---- Team Preview ----
    # Provide a concrete team preview method returning the Showdown command string.
    # Older poke-env gym wrappers expect "/team 123456" and will pass this through.
    def teampreview(self, battle: Battle) -> str:  # type: ignore[override]
        choice = super().teampreview(battle)
        print(f"[DEBUG] teampreview: returning '{choice}'", flush=True)
        return choice


PokeAgentServerConfiguration = ServerConfiguration(
    "wss://pokeagentshowdown.com/showdown/websocket",
    "https://play.pokemonshowdown.com/action.php?",
)


class PokeAgentLadder(QueueOnLocalLadder):
    """
    Battle against the PokéAgent Challenge Ladder (http://pokeagentshowdown.com.insecure.psim.us)

    Note that you must register a real Showdown account by going to the website above and clicking
    the Gear icon in the top right corner. `player_username` and `player_password` are required.

    Note:
        Be careful about auto-resets and how you handle terminating the eval loop after `num_battles`.
        Unlike a regular RL eval, creating an episode that you won't finish is a big problem because
        it will lead to a loss and a drop in rating. Test with `QueueOnLocalLadder` first!
    """
    # increases time to launch opponent envs before ladder loop times out ("Agent is not challenging").
    # may need to be especially long for PokéAgent because it takes some time for your Elo search radius
    # to expand to active players... depending on who is online and what your Elo is.
    _INIT_RETRIES = 3000

    @property
    def server_configuration(self):
        return PokeAgentServerConfiguration

    def handle_ladder_start(self, n_challenges: int):
        assert (
            self.player_username is not None and self.player_password is not None
        ), "Username and password are required for PokéAgent laddering"
        assert self.player_username.startswith(
            "PAC"
        ), "Bot usernames should start with 'PAC'"
        super().start_laddering(n_challenges)
# --- Compatibility: preview order stub ---------------------------------------
class _OrderStub:
    """Minimal object mimicking poke-env BattleOrder for preview.
    Provides `.message` for code paths that expect an order, and `__str__`
    so it can be used where a raw string is expected.
    """
    __slots__ = ("message",)

    def __init__(self, message: str):
        self.message = str(message)

    def __str__(self) -> str:
        return self.message

    def __repr__(self) -> str:
        return f"_OrderStub({self.message!r})"
